<?php
declare(strict_types=1);namespace Essivery\Partner\Controllers;
use Essivery\Api\Core\Auth;use Essivery\Api\Core\Request;use Essivery\Api\Core\Response;use Essivery\Api\Services\AuditService;use Essivery\Partner\Domain\PartnerContext;use Essivery\Partner\Repositories\PartnerReviewRepository;use Essivery\Partner\Services\PartnerReviewService;
final class PartnerReviewController{public function __construct(private array$c){}public function show(Request$r):never{Response::success($this->service()->get($this->context($r)),200,['requestId'=>$r->requestId]);}public function submit(Request$r):never{$unknown=array_diff(array_keys($r->body),['confirmed']);if($unknown)throw new \Essivery\Api\Core\ApiException(422,'VALIDATION_ERROR','Submission contains unsupported fields.','Remove unsupported fields.',['body'=>'Unsupported fields: '.implode(', ',$unknown)]);$auth=Auth::context($r);$audit=new AuditService($this->pdo());$result=$this->service()->submit($this->context($r),($r->body['confirmed']??null)===true,function($m)use($audit,$auth,$r){$event=$m['submissionType']==='resubmission'?'partner_setup.application_resubmitted':'partner_setup.application_submitted';$audit->record((int)$auth['user_id'],(int)$auth['identity_id'],$event,'partner_onboarding_application',null,$r->requestId,$m);});Response::success($result,200,['requestId'=>$r->requestId]);}private function service():PartnerReviewService{$pdo=$this->pdo();return new PartnerReviewService($pdo,new PartnerReviewRepository($pdo));}private function context(Request$r):PartnerContext{return$r->attributes['partnerContext'];}private function pdo():\PDO{return$this->c['database']->connection();}}
